create table public.action_plans (
 id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete restrict, action_number text not null unique default format('ACT-%s-%s',to_char(current_date,'YYYY'),lpad(nextval('public.problem_number_sequence')::text,6,'0')),
 source_entity_type text not null check(source_entity_type ~ '^[A-Z][A-Z_]{1,79}$'), source_entity_id uuid not null, description text not null check(length(trim(description)) between 10 and 10000), owner_id uuid references public.user_profiles(id) on delete set null, due_at timestamptz, priority smallint not null check(priority between 1 and 5), status text not null default 'PLANNED' check(status in ('PLANNED','IN_PROGRESS','COMPLETED','EFFECTIVENESS_VERIFIED')), result text, effectiveness_result text, created_by uuid not null references public.user_profiles(id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), completed_at timestamptz, effectiveness_verified_at timestamptz, effectiveness_verified_by uuid references public.user_profiles(id) on delete set null
);
create index action_plans_org_status_due_idx on public.action_plans(organization_id,status,due_at); create trigger action_plans_updated before update on public.action_plans for each row execute function public.set_updated_at(); alter table public.action_plans enable row level security;
create policy "management reads action plans" on public.action_plans for select to authenticated using(public.has_ticket_management_role(organization_id));
create or replace function public.create_action_plan_from_problem(target_problem_id uuid,target_description text,target_priority smallint,target_due_at timestamptz default null) returns uuid language plpgsql security definer set search_path=public as $$
declare p public.problems%rowtype; action_id uuid;
begin select * into p from public.problems where id=target_problem_id for update; if p.id is null or not public.has_ticket_management_role(p.organization_id) then raise exception 'ACTION_PLAN_NOT_AUTHORIZED'; end if; if length(trim(target_description)) not between 10 and 10000 or target_priority not between 1 and 5 then raise exception 'ACTION_PLAN_INVALID_INPUT'; end if;
insert into public.action_plans(organization_id,source_entity_type,source_entity_id,description,priority,due_at,created_by) values(p.organization_id,'PROBLEM',p.id,trim(target_description),target_priority,target_due_at,auth.uid()) returning id into action_id;
insert into public.entity_relationships(organization_id,source_entity_type,source_entity_id,target_entity_type,target_entity_id,relationship_type,reason,created_by) values(p.organization_id,'PROBLEM',p.id,'ACTION_PLAN',action_id,'CORRECTED_BY','Plano de ação criado.',auth.uid());
insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(p.organization_id,auth.uid(),'ACTION_PLAN_CREATED','action_plan',action_id,jsonb_build_object('problem_id',p.id),'WEB');return action_id;end; $$;
revoke all on function public.create_action_plan_from_problem(uuid,text,smallint,timestamptz) from public; grant execute on function public.create_action_plan_from_problem(uuid,text,smallint,timestamptz) to authenticated;
